function formatIsoString(isoString) {
    const match = isoString.match(/(\.\d+)(Z)$/);
    if (match) {
        let milliseconds = match[1];
        let digits = milliseconds.substring(1);

        if (digits.length < 3) {
            milliseconds = `.${digits.padEnd(3, '0')}`;
        } else if (digits.length > 3) {
            milliseconds = `.${digits.substring(0, 3)}`;
        }

        return isoString.replace(/(\.\d+)(Z)$/, `${milliseconds}$2`);
    }
    return isoString;
}

function formatComments(items, parentName) {
    if (!items.length) return '';
    return items.map(item => {
        let time = java.timeFormatUTC(new Date(formatIsoString(item.createdAt)).getTime(), 'yyyy-MM-dd HH:mm:ss', 8);
        let replyTag = parentName ? ` | @${parentName}` : '';
        let content = (parentName ? 'ㅤ' : '') + item.content;

        let block = `${parentName ? '└' + item.authorUsername : item.authorUsername} | ${time}${replyTag}\n${parentName ? content.replaceAll('\n', '\nㅤ') : content}`;

        if (item.replyCount > 0) {
            block += '\n' + formatComments(item.replies.items, item.authorUsername);
        }
        return block;
    }).join(parentName ? '\n' : '\n​\n');
}

const allComments = [];
let page = 1;
let hasMore = true;

while (hasMore && page <= 5) {
    let res;
    try {
    res = JSON.parse(java.get(`${baseUrlApi}&page=${page}`, {}).body() || '{}');
    } catch (e) {
        java.log('书评获取失败：' + e.message);
        break;
    }
    if (res.items.length) {
        allComments.push(formatComments(res.items));
        page++;
    } else {
        hasMore = false;
    }
}

const Comment = allComments.length ? `
ㅤ
💬 [书籍评论 | 时间倒序]：
${allComments.join('\n​\n')}`.replaceAll('::: star ', '评分：⭐×').replaceAll('::: details 点击展开', '').replace('\n:::\n', '') : '';

