${/\/wenku\//.test(baseUrl) ? `${$.artists.length ? '画师：' + $.artists.join(' & ') : ''}
${$.imprint ? '书系：' + $.imprint : ''}
${$.publisher ? '出版社：' + $.publisher : ''}
${String(java.getString('$.latestPublishAt')) ? '最新出版时间：' + java.timeFormatUTC(+java.getString('$.latestPublishAt') * 1000, 'yyyy-MM-dd', 8) : ''}` : `${$.titleJp}
总计：${$.toc.filter(item => item.chapterId).length} 百度：${$.baidu} 有道：${$.youdao} GPT：${$.gpt} Sakura：${$.sakura}`}
